use mill.stock;
use mill.rules;

pub fn lines() -> String {
    let planks = mill.stock.inventory();
    var labels: List<String> = [];
    var i = 0;
    while i < planks.len() {
        match planks.get(index: i) {
            Some(plank) => {
                if mill.rules.keeps(plank: plank) {
                    labels.push(item: mill.rules.label(plank: plank));
                }
            },
            None => {},
        }
        i = i + 1;
    }
    labels.join(sep: ",")
}

use stable.herd;
use stable.ledger;

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let ponies = stable.herd.lineup();
    var entries: List<String> = [];
    var i = 0;
    while i < ponies.len() {
        let pony = match ponies.get(index: i) {
            Some(p) => p,
            None => {
                break;
            },
        };
        let fed = stable.herd.feed(pony: pony, scoops: 3);
        entries.push(item: stable.ledger.to_entry(pony: fed));
        i = i + 1;
    }
    io.write(text: entries.join(sep: ","))?;
    return Ok(unit);
}

