use galley.menu;
use galley.kitchen;

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let board = galley.menu.board();
    var i = 0;
    while i < board.len() {
        if i > 0 {
            io.write(text: ";")?;
        }
        match board.get(index: i) {
            Some(dish) => galley.kitchen.serve(io: io, dish: dish)?,
            None => unit,
        };
        i = i + 1;
    }
    return Ok(unit);
}

use relay.feed;

pub fn publish(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let frames = relay.feed.frames();
    var total = 0;
    var i = 0;
    while i < frames.len() {
        let contribution = match frames.get(index: i) {
            Some(frame) => match relay.feed.decode(frame: frame) {
                Some(value) => value,
                None => 0,
            },
            None => 0,
        };
        total = total + contribution;
        i = i + 1;
    }
    relay.feed.emit(io: io, total: total)?;
    return Ok(unit);
}

use relay.feed;

pub fn publish(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let frames = relay.feed.frames();
    var total = 0;
    var i = 0;
    while i < frames.len() {
        let contribution = match frames.get(index: i) {
            Some(frame) => match relay.feed.decode(frame: frame) {
                Ok(value) => value,
                Err(_) => 0,
            },
            None => 0,
        };
        total = total + contribution;
        i = i + 1;
    }
    relay.feed.emit(io: io, total: total)?;
    return Ok(unit);
}
